def count_coprime_pairs(limit: int) -> int:
    """Pairs (a, b) with 1 <= a < b <= limit and gcd(a, b) = 1, by running Euclid's algorithm on each pair."""
    pairs: int = 0
    for b in range(2, limit + 1):
        for a in range(1, b):
            x: int = a
            y: int = b
            while y != 0:
                t: int = x % y
                x = y
                y = t
            if x == 1:
                pairs += 1
    return pairs

